import { mkdir, readdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { Injectable, Logger, ServiceUnavailableException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import type { Bucket } from '@google-cloud/storage';
import { EnvironmentError, serviceAccountCredentials } from '../../config/environment';

// Object keys are generated by the API only, from record IDs and fixed kind names; nothing user-supplied. Each record
// stores which layout its file uses (storageLayout): 1 is the original flat layout, 2 keeps each person's files in one folder.
const U = '[0-9a-f-]{36}', S = '[a-z]+(?:-[a-z]+)*';
const KEYS = [
 // Layout 1.
 `photos/${U}/${U}\\.jpg`, `documents/${U}\\.pdf`, `drivers/${U}/${U}\\.pdf`, `driver-reports/${U}/${U}\\.pdf`, `driver-consents/${U}\\.pdf`,
 // Layout 2.
 `applicants/${U}/(selfie|id-selfie)/${U}\\.jpg`, `applicants/${U}/signed/${S}-v\\d+\\.pdf`, `company-documents/(onboarding|driver-consents)/${S}/${U}\\.pdf`,
 `drivers/${U}/(documents|reports)/${S}/${U}\\.pdf`, `drivers/${U}/signed/${S}-v\\d+\\.pdf`,
];
const KEY = new RegExp(`^(${KEYS.join('|')})$`);
// Only these failure codes are logged; raw storage errors can contain bucket paths or credential details.
function storageFailureCode(error: unknown): string {
  const code = typeof error === 'object' && error !== null && 'code' in error ? String((error as { code: unknown }).code) : '';
  return /^(\d{3}|E[A-Z]+)$/.test(code) ? code : 'STORAGE_FAILED';
}

/** Private file storage for applicant photos and company documents: Google Cloud Storage in production, a local folder in development. */
@Injectable()
export class StorageService {
  private readonly logger = new Logger('Storage');
  private readonly driver: 'none' | 'local' | 'gcs';
  private readonly directory: string | null;
  private bucket: Promise<Bucket> | null = null;
  constructor(private readonly config: ConfigService) {
    this.driver = config.get('STORAGE_DRIVER') ?? 'none';
    // Production must never run without private storage: photos and signatures are required there. Staging may run
    // without a bucket (photos and signatures are then not collected), and must never use the production bucket.
    if (config.get('NODE_ENV') === 'production' && config.get('DEPLOYMENT_PURPOSE') !== 'staging' && this.driver !== 'gcs') throw new EnvironmentError('The production API requires STORAGE_DRIVER=gcs with GCS_BUCKET and GCS_CREDENTIALS_BASE64');
    this.directory = this.driver === 'local' ? resolve(config.getOrThrow<string>('STORAGE_LOCAL_DIR')) : null;
  }
  /** Photos and document signatures are only collected when storage is configured (always in production). */
  get enabled() { return this.driver !== 'none'; }
  private gcs(): Promise<Bucket> {
    this.bucket ??= import('@google-cloud/storage').then(({ Storage }) => {
      const credentials = serviceAccountCredentials(this.config.getOrThrow<string>('GCS_CREDENTIALS_BASE64'))!;
      return new Storage({ credentials: { client_email: credentials.client_email, private_key: credentials.private_key }, projectId: credentials.project_id,
        retryOptions: { autoRetry: true, maxRetries: 2 } }).bucket(this.config.getOrThrow<string>('GCS_BUCKET'));
    });
    return this.bucket;
  }
  private path(key: string) {
    const path = resolve(this.directory!, ...key.split('/'));
    if (!KEY.test(key) || !path.startsWith(this.directory! + sep)) throw new Error('Invalid storage key');
    return path;
  }
  private async run<T>(action: string, work: () => Promise<T>): Promise<T> {
    if (!this.enabled) throw new ServiceUnavailableException('File storage is not configured.');
    try { return await work(); }
    catch (error) {
      this.logger.error(`Storage ${action} failed: ${storageFailureCode(error)}`);
      throw new ServiceUnavailableException('File storage is unavailable. Please try again.');
    }
  }
  /** Stores a new object. Keys are never reused, so an existing object is never overwritten. */
  put(key: string, body: Buffer, contentType: 'image/jpeg' | 'application/pdf', options: { replaceUnrecorded?: boolean } = {}) {
    return this.run('upload', async () => {
      if (!KEY.test(key)) throw new Error('Invalid storage key');
      // Only for a saved signed copy that no record names yet: a save that stopped before its record committed.
      const replace = options.replaceUnrecorded === true;
      if (this.directory) { const path = this.path(key); await mkdir(dirname(path), { recursive: true }); await writeFile(path, body, { flag: replace ? 'w' : 'wx' }); return; }
      await (await this.gcs()).file(key).save(body, { contentType, resumable: false, validation: 'crc32c', ...(replace ? {} : { preconditionOpts: { ifGenerationMatch: 0 } }) });
    });
  }
  get(key: string): Promise<Buffer> {
    return this.run('download', async () => this.directory ? readFile(this.path(key)) : (await (await this.gcs()).file(key).download())[0]);
  }
  /** Best effort: a failed removal is logged (code only) and never fails the caller. */
  async remove(key: string): Promise<void> {
    try { await this.run('removal', async () => { if (this.directory) await rm(this.path(key), { force: true }); else await (await this.gcs()).file(key).delete({ ignoreNotFound: true }); }); }
    catch { /* logged by run() */ }
  }
  /** Stored objects under a prefix and when each was stored. Only API-generated keys are returned; anything else is never touched. */
  async list(prefix: 'drivers/' | 'driver-reports/' | 'driver-consents/' | 'company-documents/driver-consents/'): Promise<{ key: string; storedAt: Date }[]> {
    const objects = await this.run('listing', async () => {
      if (!this.directory) return (await (await this.gcs()).getFiles({ prefix, autoPaginate: true }))[0].map(file => ({ key: file.name, storedAt: new Date(String(file.metadata.timeCreated)) }));
      const root = join(this.directory, prefix);
      let names: string[];
      try { names = await readdir(root, { recursive: true }); } catch (error) { if ((error as { code?: string }).code === 'ENOENT') return []; throw error; }
      return Promise.all(names.map(async name => ({ key: prefix + name.split(sep).join('/'), storedAt: (await stat(join(root, name))).mtime })));
    });
    return objects.filter(object => KEY.test(object.key) && object.key.startsWith(prefix) && !Number.isNaN(object.storedAt.getTime()));
  }
}
export type StorageLayout = 1 | 2;
/** New files use layout 2; the column defaults to 1, so a row written by an older API during a deploy names its old path. */
export const CURRENT_LAYOUT: StorageLayout = 2;
const folder = (kind: string) => kind.toLowerCase().replace(/_/g, '-');
type Stored = { id: string; kind: string; storageLayout: StorageLayout };
/** applicants/<application>/(selfie|id-selfie)/<photo>.jpg */
export const photoKey = (photo: Stored & { applicationId: string }) => photo.storageLayout === 1 ? `photos/${photo.applicationId}/${photo.id}.jpg`
 : `applicants/${photo.applicationId}/${photo.kind === 'SELFIE' ? 'selfie' : 'id-selfie'}/${photo.id}.jpg`;
/** company-documents/onboarding/<nda|sop|contact-list>/<document>.pdf: the blank NDA, SOP and contact list versions. */
export const documentKey = (doc: Stored) => doc.storageLayout === 1 ? `documents/${doc.id}.pdf` : `company-documents/onboarding/${folder(doc.kind)}/${doc.id}.pdf`;
/** drivers/<driver>/documents/<kind>/<document>.pdf: the driver's scans. */
export const driverDocumentKey = (doc: Stored & { driverId: string }) => doc.storageLayout === 1 ? `drivers/${doc.driverId}/${doc.id}.pdf`
 : `drivers/${doc.driverId}/documents/${folder(doc.kind)}/${doc.id}.pdf`;
/** drivers/<driver>/reports/mvr/<report>.pdf: reports Safety pulls. */
export const driverReportKey = (report: Stored & { driverId: string }) => report.storageLayout === 1 ? `driver-reports/${report.driverId}/${report.id}.pdf`
 : `drivers/${report.driverId}/reports/${folder(report.kind)}/${report.id}.pdf`;
/** company-documents/driver-consents/<kind>/<document>.pdf: the blank consent form versions Safety publishes. */
export const driverConsentKey = (doc: Stored) => doc.storageLayout === 1 ? `driver-consents/${doc.id}.pdf` : `company-documents/driver-consents/${folder(doc.kind)}/${doc.id}.pdf`;
/** applicants/<application>/signed/<kind>-v<version>.pdf or drivers/<driver>/signed/<kind>-v<version>.pdf: saved signed copies. */
export const signedCopyKey = (owner: { applicationId: string } | { driverId: string }, doc: { kind: string; version: number }) =>
 `${'applicationId' in owner ? `applicants/${owner.applicationId}` : `drivers/${owner.driverId}`}/signed/${folder(doc.kind)}-v${doc.version}.pdf`;
